{!REQUIRESCRIPT ("/soap/ajax/13.0/connection.js")} 

var selected = {!GETRECORDIDS($ObjectType.Seeker__c)}; 
var updateRecords = []; 

if (selected[0] == null) { 

alert("Please select at least one Seeker Case.") 
location.reload(); 
} 

else { 

//alert(selected.length); 

for (var a=0; a<selected.length; a++) { 
var update_Case = new sforce.SObject("Seeker__c"); 
update_Case.Status__c = "Closed"; 
update_Case.Id = selected[a]; 
update_Case.OwnerId = "{!$User.Id}";
updateRecords.push(update_Case); 

} 

result = sforce.connection.update(updateRecords); 

 if (result[0].getBoolean('success')) {
           alert("Closed Successfully"); 
location.reload(); 
        } else {
            alert('An error occurred updating this record:\n\n' + result[0].errors.message);
        }



}
